export const H_EARTH_T4_INSTANCE_BUDGET=2048;
export const H_EARTH_T4_ADDED_DRAW_CALL_BUDGET=2;

export const H_EARTH_T4_INSTANCING_RENDERER_CONTRACT=Object.freeze({
  primitiveClasses:2,addedDrawCallBudget:2,instanceBudget:2048,postInitializationResourceCreation:0,postInitializationBufferUpload:0
});
export function createHEarthT4StaticInstancePackage(gl){
  const placement=H_EARTH_T4_FROZEN_PLACEMENT;
  if(placement.total>H_EARTH_T4_INSTANCE_BUDGET)throw Error('T4_INSTANCE_BUDGET');
  const tuft=placement.instances.filter(v=>v.kind==='TUFT'),rock=placement.instances.filter(v=>v.kind==='ROCK');
  if(tuft.length!==placement.counts.TUFT||rock.length!==placement.counts.ROCK)throw Error('T4_COUNT_CORRESPONDENCE');
  const tuftVertices=new Float32Array([-.10,0,0,.10,0,0,0,.70,0,0,0,-.10,0,0,.10,0,.70,0]);
  const rockVertices=new Float32Array([-.28,0,-.20,.30,0,-.18,.22,0,.25,-.20,0,.28,0,.34,0]);
  const pack=a=>new Float32Array(a.flatMap(v=>[v.x,v.elevation,v.z,v.rotation,v.scale]));
  const make=(vertices,instances)=>{const vb=gl.createBuffer(),ib=gl.createBuffer();if(!vb||!ib)throw Error('T4_BUFFER_CREATE');
    gl.bindBuffer(gl.ARRAY_BUFFER,vb);gl.bufferData(gl.ARRAY_BUFFER,vertices,gl.STATIC_DRAW);
    gl.bindBuffer(gl.ARRAY_BUFFER,ib);gl.bufferData(gl.ARRAY_BUFFER,pack(instances),gl.STATIC_DRAW);
    return{vertexBuffer:vb,instanceBuffer:ib,vertexCount:vertices.length/3,instanceCount:instances.length};};
  return Object.freeze({tuft:make(tuftVertices,tuft),rock:make(rockVertices,rock),placementSha:placement.placementSha,total:placement.total});
}
export function drawHEarthT4StaticInstances(gl,pkg,bindClass){
  let draws=0;
  for(const [kind,c] of [['TUFT',pkg.tuft],['ROCK',pkg.rock]]){if(!c.instanceCount)continue;bindClass(kind,c);
    gl.bindBuffer(gl.ARRAY_BUFFER,c.instanceBuffer);
    for(let i=0;i<5;i++){gl.enableVertexAttribArray(8+i);gl.vertexAttribPointer(8+i,1,gl.FLOAT,false,20,i*4);gl.vertexAttribDivisor(8+i,1);}
    gl.drawArraysInstanced(gl.TRIANGLES,0,c.vertexCount,c.instanceCount);draws++;}
  if(draws>2)throw Error('T4_DRAW_BUDGET');return draws;
}

export const H_EARTH_T4_LIFECYCLE_INTEGRATION_ID='H_EARTH_T4_STATIC_TWO_CLASS_LIFECYCLE_v2';

export function createHEarthRun8ER3CPersistentRendererT4(options = {}) {
  const baseRenderer = H_EARTH_T4_BASE_RENDERER_FACTORY(options);
  const gl = options.canvas?.getContext?.('webgl2');
  if (!gl) throw new Error('T4_WEBGL2_CONTEXT_UNAVAILABLE');

  let initialized = false;
  let instancePackage = null;
  let program = null;
  let positionLocation = -1;
  let viewProjectionLocation = null;
  let classColorLocation = null;
  let initializationResourceCreates = 0;
  let initializationBufferUploads = 0;
  let postInitializationResourceCreation = 0;
  let postInitializationBufferUpload = 0;
  let lastAddedDrawCalls = 0;
  let maximumAddedDrawCalls = 0;
  let framesWithT4 = 0;

  const vertexSource = `#version 300 es
precision highp float;
layout(location=0) in vec3 aPosition;
layout(location=8) in float iX;
layout(location=9) in float iY;
layout(location=10) in float iZ;
layout(location=11) in float iRotation;
layout(location=12) in float iScale;
uniform mat4 uViewProjection;
void main(){
  float c=cos(iRotation),s=sin(iRotation);
  vec3 p=aPosition*iScale;
  vec3 rotated=vec3(p.x*c-p.z*s,p.y,p.x*s+p.z*c);
  gl_Position=uViewProjection*vec4(rotated+vec3(iX,iY,iZ),1.0);
}`;
  const fragmentSource = `#version 300 es
precision highp float;
uniform vec3 uClassColor;
out vec4 outColor;
void main(){outColor=vec4(uClassColor,1.0);}`;

  const compile = (type, source) => {
    const shader=gl.createShader(type); if(!shader) throw new Error('T4_SHADER_CREATE');
    initializationResourceCreates++;
    gl.shaderSource(shader,source); gl.compileShader(shader);
    if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS)) throw new Error('T4_SHADER_COMPILE:'+gl.getShaderInfoLog(shader));
    return shader;
  };

  const initialize = (packet) => {
    if(initialized) throw new Error('T4_RENDERER_ALREADY_INITIALIZED');
    const baseReceipt=baseRenderer.initialize(packet);
    const vs=compile(gl.VERTEX_SHADER,vertexSource), fs=compile(gl.FRAGMENT_SHADER,fragmentSource);
    program=gl.createProgram(); if(!program) throw new Error('T4_PROGRAM_CREATE'); initializationResourceCreates++;
    gl.attachShader(program,vs); gl.attachShader(program,fs); gl.linkProgram(program);
    if(!gl.getProgramParameter(program,gl.LINK_STATUS)) throw new Error('T4_PROGRAM_LINK:'+gl.getProgramInfoLog(program));
    gl.deleteShader(vs); gl.deleteShader(fs);
    viewProjectionLocation=gl.getUniformLocation(program,'uViewProjection');
    classColorLocation=gl.getUniformLocation(program,'uClassColor');
    if(viewProjectionLocation===null||classColorLocation===null) throw new Error('T4_UNIFORM_LOCATION');
    instancePackage=createHEarthT4StaticInstancePackage(gl);
    initializationResourceCreates+=4;
    initializationBufferUploads+=4;
    initialized=true;
    return {...baseReceipt,t4:getT4Receipt()};
  };

  const bindClass = (kind, c) => {
    gl.useProgram(program);
    gl.bindBuffer(gl.ARRAY_BUFFER,c.vertexBuffer);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0,3,gl.FLOAT,false,12,0);
    gl.uniform3fv(classColorLocation,kind==='TUFT'?new Float32Array([0.20,0.38,0.16]):new Float32Array([0.34,0.31,0.27]));
  };

  const renderFrame = (packet) => {
    if(!initialized||!instancePackage||!program) throw new Error('T4_RENDERER_NOT_INITIALIZED');
    baseRenderer.renderFrame(packet);
    gl.useProgram(program);
    gl.uniformMatrix4fv(viewProjectionLocation,false,new Float32Array(packet.camera.viewProjectionMatrix));
    lastAddedDrawCalls=drawHEarthT4StaticInstances(gl,instancePackage,bindClass);
    maximumAddedDrawCalls=Math.max(maximumAddedDrawCalls,lastAddedDrawCalls);
    framesWithT4++;
    if(lastAddedDrawCalls>H_EARTH_T4_ADDED_DRAW_CALL_BUDGET) throw new Error('T4_DRAW_BUDGET_RUNTIME');
  };

  const getT4Receipt = () => Object.freeze({
    lifecycleIntegrationId:H_EARTH_T4_LIFECYCLE_INTEGRATION_ID,
    placementSha:H_EARTH_T4_FROZEN_PLACEMENT.placementSha,
    total:H_EARTH_T4_FROZEN_PLACEMENT.total,
    counts:H_EARTH_T4_FROZEN_PLACEMENT.counts,
    instanceBudget:H_EARTH_T4_INSTANCE_BUDGET,
    addedDrawCallBudget:H_EARTH_T4_ADDED_DRAW_CALL_BUDGET,
    lastAddedDrawCalls,
    maximumAddedDrawCalls,
    framesWithT4,
    initializationResourceCreates,
    initializationBufferUploads,
    postInitializationResourceCreation,
    postInitializationBufferUpload,
    frozenPlacementCorrespondence:instancePackage?.placementSha===H_EARTH_T4_FROZEN_PLACEMENT.placementSha&&instancePackage?.total===647,
    noPostInitializationResourceCreation:postInitializationResourceCreation===0,
    noPostInitializationBufferUpload:postInitializationBufferUpload===0
  });

  return Object.freeze({
    rendererId:H_EARTH_RUN_8E_R3C_RENDERER_ID,
    t4LifecycleIntegrationId:H_EARTH_T4_LIFECYCLE_INTEGRATION_ID,
    initialize,
    renderFrame,
    presentColorFrame:baseRenderer.presentColorFrame,
    captureColorFrame:baseRenderer.captureColorFrame,
    captureDepthSummary:baseRenderer.captureDepthSummary,
    getResourceReceipt:()=>({...baseRenderer.getResourceReceipt(),t4:getT4Receipt()})
  });
}

export { createHEarthRun8ER3CPersistentRendererT4 as createHEarthRun8ER3CPersistentRenderer };
export default createHEarthRun8ER3CPersistentRendererT4;
